{"code":"def transform(grid):
    # The solid 5 row separates the two samples.  Compare each colored
    # vertical mark's increase in length across that separator.
    sep = next(i for i,r in enumerate(grid) if r and all(x == 5 for x in r))
    above, below = grid[:sep], grid[sep+1:]
    colors = []
    for r in grid:
        for x in r:
            if x not in (0,5) and x not in colors:
                colors.append(x)
    best = colors[0]
    bestdelta = -10**9
    for c in colors:
        a = sum(x == c for r in above for x in r)
        b = sum(x == c for r in below for x in r)
        if b-a > bestdelta:
            bestdelta, best = b-a, c
    return [[best,best],[best,best]]"}

